import {PHASES,FOREST_PATH,ROUTES,RESULT,CELLS,WIRE,interval,clamp} from './model.mjs';
const FOREST='assets/forest-banteng-wire-v02.png',MAP='assets/original-fig11-map.jpeg';
let svg,refs={},ready=false,latest=null,timeline;
const camera={zoom:1,x:800,y:450};
const $=id=>refs[id]||(refs[id]=svg.querySelector(`#${id}`));
const n=v=>Number(v).toFixed(3);
const path=pts=>pts.map(([x,y],i)=>`${i?'L':'M'}${x} ${y}`).join(' ');
function pointAt(points,p){const lengths=points.slice(1).map((b,i)=>Math.hypot(b[0]-points[i][0],b[1]-points[i][1]));let distance=clamp(p)*lengths.reduce((a,b)=>a+b,0);for(let i=0;i<lengths.length;i++){if(distance<=lengths[i]||i===lengths.length-1){const f=distance/lengths[i];return [points[i][0]+(points[i+1][0]-points[i][0])*f,points[i][1]+(points[i+1][1]-points[i][1])*f];}distance-=lengths[i];}return points.at(-1);}
function grid(prefix,x,y,predicted){return `<g transform="translate(${x} ${y})">${CELLS.map((c,i)=>{const cx=(i%6)*88,cy=Math.floor(i/6)*88;return `<g><rect id="${prefix}-cell-${i}" x="${cx}" y="${cy}" width="80" height="80" rx="2" class="grid-cell"/><rect id="${prefix}-unc-${i}" x="${cx+6}" y="${cy+6}" width="68" height="68" rx="1" class="uncertain"/>${!predicted&&c.observed?`<circle cx="${cx+40}" cy="${cy+40}" r="11" class="observed"/>`:''}${!predicted&&[0,5,23].includes(i)?`<text class="label muted" x="${cx+40}" y="${cy+50}" text-anchor="middle">？</text>`:''}</g>`;}).join('')}</g>`;}
function markup(){return `<svg xmlns="http://www.w3.org/2000/svg" class="paws-scene" viewBox="0 0 1600 900" role="img" aria-label="從森林查找、巡護紀錄和不確定性，連到Srepok真實風險分組試驗的動畫"><style>
.paws-scene{--p:#f3f0e8;--ink:#26332f;--muted:#5b6a60;--line:#a6b0a7;--accent:#526f61;--route:#287e94;--amber:#ae752b;--high:#b55748;--medium:#a58b2f;--low:#52765b;font-family:var(--font-sans,'PingFang TC',sans-serif);background:var(--p)}
html[data-theme=dark] .paws-scene{--p:#1b1e1f;--ink:#f0eee7;--muted:#b9bdbb;--line:#737e79;--accent:#cdbb95;--route:#83c9d3;--amber:#eac17d;--high:#e59a89;--medium:#ddc46f;--low:#a6c49a}
.paws-scene text{fill:var(--ink)}.paper{fill:var(--p)}.title{font:500 43px var(--font-serif,'Songti TC',serif)}.big{font:500 49px var(--font-serif,'Songti TC',serif)}.label{font-size:29px;font-weight:500}.copy{font-size:24px}.small{font-size:19px;fill:var(--muted)}.muted{fill:var(--muted)}.chip{fill:var(--p);opacity:.95}.line{fill:none;stroke:var(--line);stroke-width:2}.layer{visibility:hidden;opacity:0}.route{fill:none;stroke:var(--route);stroke-width:7;stroke-linecap:round;stroke-linejoin:round}.uncertain{fill:none;stroke:var(--ink);stroke-width:2.5;stroke-dasharray:5 6;opacity:0}.grid-cell{fill:var(--p);stroke:var(--line);stroke-width:1.5}.observed{fill:var(--amber)}.score{font:500 51px var(--font-serif,'Songti TC',serif);font-variant-numeric:tabular-nums}.future-point{fill:var(--p);stroke:var(--route);stroke-width:4}.result-bar{fill:var(--high)}.result-track{fill:var(--line);opacity:.16}
</style><defs><clipPath id="world-clip"><rect x="0" y="126" width="1600" height="725"/></clipPath><clipPath id="route-map-clip"><rect x="810" y="190" width="735" height="620" rx="3"/></clipPath><symbol id="ranger" viewBox="0 0 60 120"><g fill="#f3e5bf" stroke="#243e35" stroke-width="3"><circle cx="30" cy="18" r="10"/><path d="M18 30L40 30L45 66L35 70L41 111L30 111L25 77L20 111L9 111L15 66Z"/><path d="M16 35L5 65M39 35L52 61"/></g></symbol></defs>
<rect class="paper" width="1600" height="900"/>
<g id="world" class="layer" clip-path="url(#world-clip)"><g id="forest-camera"><image href="${FOREST}" width="1600" height="900" preserveAspectRatio="xMidYMid slice"/><g id="walk"><path id="forest-route-shadow" d="${path(FOREST_PATH)}" fill="none" stroke="#183d3c" stroke-width="12" stroke-linecap="round"/><path id="forest-route" d="${path(FOREST_PATH)}" class="route" style="stroke:#a4dce1"/><g id="ranger-position"><use href="#ranger" x="-22" y="-77" width="44" height="88"/></g></g><ellipse id="wire-halo" cx="${WIRE.x}" cy="${WIRE.y}" rx="115" ry="51" fill="none" stroke="#f6d193" stroke-width="4"/></g></g>
<g id="opening" class="layer"><rect class="chip" x="850" y="177" width="689" height="168" rx="3"/><text class="big" id="opening-line-1" x="880" y="244">森林裡的動物，</text><text class="copy" id="opening-line-2" x="882" y="305">也面對隱蔽陷阱的威脅。</text></g>
<g id="coverage" class="layer"><rect class="chip" x="58" y="519" width="670" height="238" rx="3"/><text class="big" x="86" y="589">走過的，只是一部分。</text><text class="copy" x="88" y="648">這條路徑沒有經過鋼索附近。</text><text class="copy" x="88" y="692">紀錄上沒查獲，現場也可能還有陷阱。</text><text class="small" x="88" y="734">路徑與人員為示意；鋼索的位置始終相同。</text></g>
<g id="prediction" class="layer"><text class="label" x="78" y="211">過去怎麼巡、查到什麼？</text><text class="label" x="926" y="211">各區查獲可能性與預測把握</text>${grid('past',78,266,false)}${grid('estimate',926,266,true)}<path class="line" style="stroke:var(--accent);stroke-width:4" d="M660 434H844M822 414L844 434L822 454"/><text class="label" x="750" y="401" text-anchor="middle">PAWS</text><path class="route" d="M93 642H141"/><text class="copy" x="159" y="651">巡護紀錄</text><circle class="observed" cx="357" cy="642" r="10"/><text class="copy" x="379" y="651">查獲紀錄</text><text class="small" x="78" y="692">再結合地形、道路與環境資料</text><text class="copy" x="926" y="651">底色：預期查獲風險</text><text class="copy" id="uncertainty-key" x="926" y="698">虛線：預測較沒把握</text><text class="label" x="800" y="769" text-anchor="middle">「沒查獲」的可信程度，也和巡護努力有關。</text><text class="copy muted" x="800" y="817" text-anchor="middle">資料留下的空白，需要處理；模型的預測把握，也要保留。</text></g>
<g id="planning" class="layer"><text class="label" x="66" y="211">同樣的巡護資源，怎麼選？</text><text class="small" x="450" y="274" text-anchor="middle">預期查獲指標</text><text class="small" x="660" y="274" text-anchor="middle">規劃用分數</text><path class="line" d="M65 295H770M65 470H770M65 628H770"/><g id="plan-row-a"><text class="label" x="68" y="357">A</text><text class="copy" x="68" y="410">預測較沒把握</text><text class="score" x="450" y="399" text-anchor="middle">72</text><text class="score" id="score-a" x="660" y="399" text-anchor="middle">72</text></g><g id="plan-row-b"><text class="label" x="68" y="522">B</text><text class="copy" x="68" y="575">預測較有把握</text><text class="score" x="450" y="564" text-anchor="middle">65</text><text class="score" id="score-b" x="660" y="564" text-anchor="middle">65</text></g><text class="copy" id="planning-decision" x="68" y="687">先看預期查獲，A的指標較高。</text><text class="copy muted" x="68" y="744">加入不確定性的扣分，</text><text class="copy muted" x="68" y="786">較有把握的方案可能變得更值得優先考慮。</text><g clip-path="url(#route-map-clip)"><rect x="810" y="190" width="735" height="620" fill="var(--line)" opacity=".09"/>${Array.from({length:11},(_,i)=>`<path class="line" style="stroke-width:1;opacity:.35" d="M${820+i*64} 230V795"/>`).join('')}${Array.from({length:9},(_,i)=>`<path class="line" style="stroke-width:1;opacity:.35" d="M820 ${235+i*64}H1530"/>`).join('')}<circle class="future-point" cx="905" cy="314" r="35" style="stroke-dasharray:5 6"/><circle class="future-point" cx="1375" cy="314" r="35" style="stroke:var(--amber)"/><text class="label" x="905" y="269" text-anchor="middle">A</text><text class="label" x="1375" y="269" text-anchor="middle">B</text><path id="route-a" class="route" d="${path(ROUTES.A)}"/><path id="route-b" class="route" style="stroke:var(--amber)" d="${path(ROUTES.B)}"/><circle cx="1140" cy="714" r="13" fill="var(--ink)"/><text class="copy" x="1140" y="772" text-anchor="middle">同一據點</text></g><text class="small" x="1175" y="835" text-anchor="middle">概念路線，沒有地理座標或實際距離。</text></g>
<g id="field" class="layer"><image id="official-map" href="${MAP}" x="52" y="151" width="605" height="690" preserveAspectRatio="xMidYMid meet"/><text class="label" x="731" y="195">Srepok第一次現場試驗</text><text class="copy muted" x="731" y="239">2018年12月—2019年1月</text><text class="small" x="731" y="283">原圖彩色方格＝風險分組；藍點＝巡護據點。</text>${RESULT.map((r,i)=>`<g id="result-${i}" transform="translate(735 ${332+i*145})"><text class="label" x="0" y="0">${r.label}</text><text class="big" x="760" y="8" text-anchor="end">${r.observed}／${r.patrolled}</text><rect class="result-track" y="35" width="760" height="23"/><rect id="bar-${i}" class="result-bar" y="35" width="${760*r.observed/r.patrolled}" height="23" style="fill:var(--${r.id})"/></g>`).join('')}<text class="copy" x="735" y="780">查獲跡象格數／實際巡過格數｜1×1公里</text><text class="small" x="735" y="824" id="field-limit">巡護員事前不知道高、中、低風險分組。</text></g>
<g id="ending" class="layer"><rect class="chip" x="830" y="178" width="713" height="235" rx="3"/><text class="big" x="858" y="248">AI提供查找線索，</text><text class="big" x="858" y="314">巡護員在現場確認。</text><text class="copy" x="861" y="378">分組有辨別力，仍需要人的判斷與查找。</text><rect class="chip" x="60" y="608" width="895" height="155" rx="3"/><text class="label" x="88" y="664">高風險選區，較常查獲盜獵跡象。</text><text class="copy" x="88" y="722">查獲成果，還不能直接推成族群恢復。</text></g>
<rect class="paper" width="1600" height="126"/><text id="headline" class="title" x="52" y="63"/><text id="subtitle" class="copy muted" x="54" y="105"/><rect class="paper" y="851" width="1600" height="49"/><text id="disclosure" class="small" x="32" y="883"/><text id="stage-time" class="small" x="1566" y="883" text-anchor="end"/>
</svg>`;}
function preload(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>i.decode().then(resolve,resolve);i.onerror=()=>reject(new Error('畫面素材尚未載入，請重新載入。'));i.src=src;});}
function text(id,value){if($(id).textContent!==String(value))$(id).textContent=String(value);}
function opacity(id,v){$(id).style.opacity=n(v);$(id).style.visibility=v>.0001?'visible':'hidden';}
function revealPath(id,p){const el=$(id),len=el.getTotalLength();el.style.strokeDasharray=String(len);el.style.strokeDashoffset=String(len*(1-clamp(p)));}
export async function initScene(element){ready=false;refs={};timeline?.kill();Object.assign(camera,{zoom:1,x:800,y:450});element.innerHTML=markup();svg=element.querySelector('svg');svg.style.cssText='display:block;width:100%;height:100%';if(!window.gsap)throw new Error('動畫序列未載入，請重新載入。');timeline=gsap.timeline({paused:true});timeline.to(camera,{zoom:1.65,x:WIRE.x,y:WIRE.y,duration:5,ease:'power2.inOut'},8).set(camera,{zoom:1,x:800,y:450},18).to(camera,{zoom:1.025,duration:14,ease:'none'},116);await Promise.all([FOREST,MAP].map(preload));ready=true;}
export function renderScene(s){if(!ready)return;latest=s;timeline.time(s.time,false);const p=PHASES[s.phase],edge=Math.min(s.phase===0?1:interval(s.time,p.start,p.start+.4),s.phase===5?1:interval(p.end-s.time,0,.35));
 for(const [i,id] of ['opening','coverage','prediction','planning','field','ending'].entries())opacity(id,s.phase===i?edge:0);
 opacity('world',[0,1,5].includes(s.phase)?edge:0);opacity('walk',s.phase===1?1:0);opacity('wire-halo',s.phase===0?interval(s.time,11,14):s.phase===1?interval(s.time,30,34):0);
 let z=camera.zoom,cx=camera.x,cy=camera.y;if(s.reducedMotion){z=s.phase===0&&s.time>=10?1.65:1;cx=z>1?WIRE.x:800;cy=z>1?WIRE.y:450;}
 const tx=clamp(800-z*cx,1600*(1-z),0),ty=clamp(450-z*cy,900*(1-z),0);$('forest-camera').setAttribute('transform',`translate(${n(tx)} ${n(ty)}) scale(${n(z)})`);
 text('opening-line-1',s.time<10?'森林裡的動物，':'鋼索藏在枯葉間。');text('opening-line-2',s.time<10?'也面對隱蔽陷阱的威脅。':'走近、看見，才可能留下查獲紀錄。');
 revealPath('forest-route',s.patrolProgress);revealPath('forest-route-shadow',s.patrolProgress);const [x,y]=pointAt(FOREST_PATH,s.patrolProgress);$('ranger-position').setAttribute('transform',`translate(${n(x)} ${n(y)})`);
 for(const c of CELLS){const a=$(`past-cell-${c.id}`),b=$(`estimate-cell-${c.id}`);a.style.fill=c.visited?'var(--accent)':'var(--p)';a.style.fillOpacity=c.visited?'.28':'1';b.style.fill=`var(--${c.risk>.6?'high':c.risk>.35?'medium':'low'})`;b.style.fillOpacity=n(s.predictionProgress*(.16+c.risk*.55));opacity(`past-unc-${c.id}`,0);opacity(`estimate-unc-${c.id}`,c.uncertainty>.55?s.uncertaintyProgress:0);}
 opacity('uncertainty-key',s.uncertaintyProgress);const plan=s.planning;text('score-a',Math.round(plan.scoreA));text('score-b',Math.round(plan.scoreB));$('plan-row-a').style.opacity='1';$('plan-row-b').style.opacity='1';$('score-a').style.fill=plan.selected==='A'?'var(--ink)':'var(--muted)';$('score-b').style.fill=plan.selected==='B'?'var(--ink)':'var(--muted)';
 for(const id of ['a','b']){revealPath(`route-${id}`,plan.routeProgress);$(`route-${id}`).style.opacity=plan.selected===id.toUpperCase()?'1':'.22';}
 text('planning-decision',plan.beta===0?'先看預期查獲，A的指標較高。':plan.selected==='A'?'加入不確定性的扣分，再比較。':'納入預測把握，B的規劃分數較高。');
 for(let i=0;i<3;i++){opacity(`result-${i}`,i<s.field.revealCount?1:0);const amount=interval(s.time,[90,98,104][i],[93,101,107][i]);$(`bar-${i}`).setAttribute('transform',`scale(${n(amount)} 1)`);}
 text('field-limit',s.time<109?'巡護員事前不知道高、中、低風險分組。':'0／36是當次未查獲，不等於證明沒有陷阱。');
 const subtitles=['Srepok棲地背景概念｜爪哇野牛與旱季森林','鋼索固定在原地；巡護員只沿這條示意路徑走過。','在給定巡護努力下，估計查獲盜獵跡象的可能性。','兩條路線資源相同；規劃分數也考慮預測不確定性。','作者原圖與Table III｜查獲格數，不是陷阱數。','歷史現場試驗支持風險分組；現場確認仍由巡護員完成。'];
 const notes=['AI生成概念圖，非研究現場照片；鋼索與動物不是實際觀測紀錄。','巡護路徑、人員與位置為教學示意，不是研究GPS軌跡。','估計的是查獲可能性，不是陷阱真實存在率；格網為教學示意，未執行模型。','所有分數為教學例，不是機率或論文輸出；路線不疊到研究原圖。','Xu et al. (2019), Fig.11 / Table III｜Srepok，2018年12月至2019年1月。','森林為AI生成情境；查獲結果不能直接換算成挽救動物數或族群恢復。'];
 text('headline',s.narrative.title||p.title);text('subtitle',subtitles[s.phase]);text('disclosure',notes[s.phase]);text('stage-time',`${String(Math.floor(s.time/60)).padStart(2,'0')}:${String(Math.floor(s.time%60)).padStart(2,'0')}`);
}
export function getSceneState(){return {ready,time:latest?.time??0,phaseId:latest?.phaseId??null,wire:{...WIRE},wireMoved:false,wireDetected:false,camera:{zoom:camera.zoom,x:camera.x,y:camera.y},routeSelected:latest?.planning.selected??null,routeCosts:latest?{A:latest.planning.costA,B:latest.planning.costB}:null,officialMapSource:MAP,officialMapHasRouteOverlay:false,fieldResults:RESULT.map(r=>({...r})),hasAudio:false};}
